Rule.Source:
  import org.apache.log4j.Logger;

  import sailpoint.object.Custom;
  import sailpoint.object.Application;
  import sailpoint.tools.Util;	

  Logger logger = Logger.getLogger("IAM_COE_BIRTHRIGHT_PROVISIONING");
  if (logger.isTraceEnabled()) {
    logger.trace("Entered to Alpha-Rule-GroupAggregationRefresh-Requestable-Population Rule!!!");
  }
  Custom customObject = context.getObjectByName(Custom.class, "Alpha-Custom-Requestable-Entitlements"); 
  String appName = groupApplication.getName(); 
  logger.debug("Alpha-Rule-GroupAggregationRefresh-Requestable-Population -> Application Name : "+appName);
  String description = obj.getAttribute("Description");
  logger.debug("Alpha-Rule-GroupAggregationRefresh-Requestable-Population -> Description : "+description); 

  if (customObject != null) { 
    List<String> entitlements = customObject.get(appName); 
    if (entitlements !=null && Util.isNotNullOrEmpty(description)) { 
      if (entitlements.contains(description)) { 
        accountGroup.setRequestable(true); 
      } 
      else { 
        accountGroup.setRequestable(false); 
      } 
    } 
  } 
  else { 
    logger.debug("Alpha-Rule-GroupAggregationRefresh-Requestable-Population -> CustomObject not found for application"); 
  }
  if (logger.isTraceEnabled()) {
    logger.trace("Alpha-Rule-GroupAggregationRefresh-Requestable-Population Rule Ended!!!");
  }
